window.__JJ_CSS_TEXT__ = "/* 鲸鲸阅读器基础样式（Task 10）：排版变量 + 正文字体栈 + 阅读基线。\r\n   运行时由 web/src/settings.js 的 applySettings 覆写 --font-size / --line-height / --content-width /\r\n   --font-cjk / --font-mono / --toc-width；颜色变量在 light.css（含 :root 兜底）与 dark.css（html[data-theme='dark']）里定义。\r\n   本文件只放排版与元素基线，不放颜色字面量（T1 carry-forward：不依赖 base/layout/code 的跨文件级联）。 */\r\n\r\n:root {\r\n  /* 排版（applySettings 运行时覆写，这里是与宿主默认值一致的兜底） */\r\n  --font-size: 16px;\r\n  --line-height: 1.7;\r\n  --content-width: 780px;\r\n  --font-cjk: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', sans-serif;\r\n  --font-mono: consolas, 'Cascadia Mono', monospace;\r\n\r\n  /* 布局（TOC 宽度与工具条高度；--toc-width 由 applySettings 按设置写入（180–360，默认 240），此处为同值兜底） */\r\n  --toc-width: 240px;\r\n  --toolbar-height: 40px;\r\n  --radius: 8px;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nhtml,\r\nbody {\r\n  height: 100%;\r\n}\r\n\r\nhtml {\r\n  scroll-behavior: smooth;\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n  background: var(--bg);\r\n  color: var(--fg);\r\n  font-family: var(--font-cjk);\r\n  font-size: var(--font-size);\r\n  line-height: var(--line-height);\r\n  text-rendering: optimizeLegibility;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\n::selection {\r\n  background: var(--selection-bg);\r\n}\r\n\r\na {\r\n  color: var(--link);\r\n  text-decoration: none;\r\n}\r\n\r\na:hover {\r\n  color: var(--link-hover);\r\n  text-decoration: underline;\r\n}\r\n\r\nimg {\r\n  max-width: 100%;\r\n  height: auto;\r\n}\r\n\r\nh1,\r\nh2,\r\nh3,\r\nh4,\r\nh5,\r\nh6 {\r\n  margin: 1.6em 0 0.6em;\r\n  font-weight: 650;\r\n  line-height: 1.3;\r\n}\r\n\r\nh1 {\r\n  font-size: 1.75em;\r\n  padding-bottom: 0.3em;\r\n  border-bottom: 1px solid var(--border);\r\n}\r\n\r\nh2 {\r\n  font-size: 1.4em;\r\n  padding-bottom: 0.25em;\r\n  border-bottom: 1px solid var(--border);\r\n}\r\n\r\nh3 {\r\n  font-size: 1.2em;\r\n}\r\n\r\nh4 {\r\n  font-size: 1.05em;\r\n}\r\n\r\nh5,\r\nh6 {\r\n  font-size: 1em;\r\n}\r\n\r\np {\r\n  margin: 0.9em 0;\r\n}\r\n\r\nul,\r\nol {\r\n  margin: 0.9em 0;\r\n  padding-left: 1.6em;\r\n}\r\n\r\nli + li {\r\n  margin-top: 0.25em;\r\n}\r\n\r\nblockquote {\r\n  margin: 1em 0;\r\n  padding: 0.2em 1em;\r\n  border-left: 4px solid var(--blockquote-border);\r\n  color: var(--blockquote-fg);\r\n}\r\n\r\nblockquote > :first-child {\r\n  margin-top: 0;\r\n}\r\n\r\nblockquote > :last-child {\r\n  margin-bottom: 0;\r\n}\r\n\r\nhr {\r\n  height: 1px;\r\n  margin: 1.6em 0;\r\n  border: 0;\r\n  background: var(--hr-bg);\r\n}\r\n\r\nmark {\r\n  background: var(--mark-bg);\r\n  color: inherit;\r\n  padding: 0 0.15em;\r\n  border-radius: 3px;\r\n}\r\n\r\nkbd {\r\n  display: inline-block;\r\n  padding: 0.1em 0.4em;\r\n  border: 1px solid var(--border);\r\n  border-bottom-width: 2px;\r\n  border-radius: 4px;\r\n  background: var(--bg-muted);\r\n  font-family: var(--font-mono);\r\n  font-size: 0.85em;\r\n  line-height: 1.4;\r\n}\r\n\r\nsub,\r\nsup {\r\n  font-size: 0.75em;\r\n  line-height: 0;\r\n}\r\n\r\nabbr[title] {\r\n  text-decoration: underline dotted;\r\n  cursor: help;\r\n}\r\n\r\ntable {\r\n  display: block;\r\n  width: max-content;\r\n  max-width: 100%;\r\n  margin: 1em 0;\r\n  border-collapse: collapse;\r\n  overflow-x: auto;\r\n}\r\n\r\nth,\r\ntd {\r\n  padding: 6px 13px;\r\n  border: 1px solid var(--table-border);\r\n}\r\n\r\nth {\r\n  background: var(--table-head-bg);\r\n  font-weight: 600;\r\n}\r\n\r\ndetails {\r\n  margin: 1em 0;\r\n}\r\n\r\nsummary {\r\n  cursor: pointer;\r\n}\r\n\r\n/* 脚注（markdown-it-footnote） */\r\n.footnotes {\r\n  margin-top: 2.4em;\r\n  padding-top: 0.8em;\r\n  border-top: 1px solid var(--border);\r\n  font-size: 0.9em;\r\n}\r\n\r\n.footnotes ol {\r\n  padding-left: 1.4em;\r\n}\r\n\r\n.footnote-ref a {\r\n  text-decoration: none;\r\n}\r\n\r\n.footnote-backref {\r\n  text-decoration: none;\r\n}\r\n\r\n/* 任务清单（markdown-it-task-lists，只读 checkbox） */\r\nul.contains-task-list {\r\n  padding-left: 1.2em;\r\n  list-style: none;\r\n}\r\n\r\nli.task-list-item > input[type='checkbox'] {\r\n  margin: 0 0.45em 0.1em 0;\r\n  vertical-align: middle;\r\n  accent-color: var(--accent);\r\n}\r\n\r\n/* 引擎缺失时的兜底渲染（保证不白屏） */\r\n.jj-fallback {\r\n  margin: 0;\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n  font-family: var(--font-mono);\r\n  font-size: 0.9em;\r\n}\r\n\r\n/* 细滚动条（WebView2 / Chromium） */\r\n::-webkit-scrollbar {\r\n  width: 10px;\r\n  height: 10px;\r\n}\r\n\r\n::-webkit-scrollbar-thumb {\r\n  background: var(--scrollbar-thumb);\r\n  border-radius: 5px;\r\n}\r\n\n/* 代码与高亮（Task 10）：行内代码/代码块/复制按钮 + highlight.js token 配色。\r\n   token 色值做成 CSS 变量（--hljs-*），由 light.css / dark.css 按 data-theme 提供，\r\n   本文件只做「hljs class → 变量」的映射（T1 carry-forward：不跨文件级联字面量色值）。 */\r\n\r\npre,\r\ncode,\r\nkbd,\r\nsamp {\r\n  font-family: var(--font-mono);\r\n}\r\n\r\ncode {\r\n  padding: 0.15em 0.35em;\r\n  border-radius: 4px;\r\n  background: var(--inline-code-bg);\r\n  font-size: 0.9em;\r\n}\r\n\r\npre {\r\n  font-size: 0.9em;\r\n  line-height: 1.55;\r\n}\r\n\r\npre code {\r\n  padding: 0;\r\n  background: none;\r\n  font-size: 1em;\r\n}\r\n\r\n/* 围栏代码块（T6 结构：div.code-wrap > pre > code.hljs + button.copy） */\r\n.code-wrap {\r\n  margin: 16px auto;\r\n}\r\n\r\n.code-wrap pre {\r\n  margin: 0;\r\n  padding: 14px 16px;\r\n  border: 1px solid var(--code-border);\r\n  border-radius: var(--radius);\r\n  background: var(--code-bg);\r\n  color: var(--code-fg);\r\n}\r\n\r\n.code-wrap .copy {\r\n  position: absolute;\r\n  top: 8px;\r\n  right: 8px;\r\n  height: 26px;\r\n  padding: 0 10px;\r\n  border: 1px solid var(--code-border);\r\n  border-radius: 6px;\r\n  background: var(--bg-elevated);\r\n  color: var(--fg-muted);\r\n  font: inherit;\r\n  font-size: 12px;\r\n  line-height: 24px;\r\n  cursor: pointer;\r\n  opacity: 0;\r\n  transition:\r\n    opacity 0.15s ease,\r\n    color 0.12s ease,\r\n    border-color 0.12s ease;\r\n}\r\n\r\n.code-wrap:hover .copy,\r\n.code-wrap .copy:focus-visible {\r\n  opacity: 1;\r\n}\r\n\r\n/* 复制结果只闪一下：enhance.js 在成功/失败后写 data-copied / data-failed，260ms 后移除属性，\r\n   颜色再经 0.12s 过渡回落，避免按钮长期停留在高亮态。 */\r\n.code-wrap .copy[data-copied='1'] {\r\n  color: var(--accent);\r\n  border-color: var(--accent);\r\n  opacity: 1;\r\n}\r\n\r\n.code-wrap .copy[data-failed='1'] {\r\n  color: #cf222e;\r\n  border-color: #cf222e;\r\n  opacity: 1;\r\n}\r\n\r\n/* highlight.js token → CSS 变量 */\r\n.hljs {\r\n  color: var(--hljs-fg);\r\n  background: transparent;\r\n}\r\n\r\n.hljs-comment,\r\n.hljs-quote {\r\n  color: var(--hljs-comment);\r\n  font-style: italic;\r\n}\r\n\r\n.hljs-keyword,\r\n.hljs-selector-tag,\r\n.hljs-doctag,\r\n.hljs-formula {\r\n  color: var(--hljs-keyword);\r\n}\r\n\r\n.hljs-string,\r\n.hljs-regexp,\r\n.hljs-char.escape_ {\r\n  color: var(--hljs-string);\r\n}\r\n\r\n.hljs-number,\r\n.hljs-symbol,\r\n.hljs-bullet,\r\n.hljs-link {\r\n  color: var(--hljs-number);\r\n}\r\n\r\n.hljs-title,\r\n.hljs-title.function_,\r\n.hljs-title.class_,\r\n.hljs-title.class_.inherited__ {\r\n  color: var(--hljs-title);\r\n}\r\n\r\n.hljs-built_in,\r\n.hljs-builtin-name {\r\n  color: var(--hljs-built-in);\r\n}\r\n\r\n.hljs-literal {\r\n  color: var(--hljs-literal);\r\n}\r\n\r\n.hljs-type,\r\n.hljs-class .hljs-title {\r\n  color: var(--hljs-type);\r\n}\r\n\r\n.hljs-attr,\r\n.hljs-attribute,\r\n.hljs-property {\r\n  color: var(--hljs-attr);\r\n}\r\n\r\n.hljs-variable,\r\n.hljs-template-variable,\r\n.hljs-params {\r\n  color: var(--hljs-variable);\r\n}\r\n\r\n.hljs-tag,\r\n.hljs-name,\r\n.hljs-selector-id,\r\n.hljs-selector-class {\r\n  color: var(--hljs-tag);\r\n}\r\n\r\n.hljs-section {\r\n  color: var(--hljs-section);\r\n}\r\n\r\n.hljs-meta {\r\n  color: var(--hljs-meta);\r\n}\r\n\r\n.hljs-addition {\r\n  color: var(--hljs-addition-fg);\r\n  background: var(--hljs-addition-bg);\r\n}\r\n\r\n.hljs-deletion {\r\n  color: var(--hljs-deletion-fg);\r\n  background: var(--hljs-deletion-bg);\r\n}\r\n\r\n.hljs-emphasis {\r\n  font-style: italic;\r\n}\r\n\r\n.hljs-strong {\r\n  font-weight: 600;\r\n}\r\n\r\n/* T11 大文件模式：关闭代码高亮后不再套 hljs 主题色，代码块用正文颜色（结构/复制按钮不变） */\r\nbody.huge-mode .hljs {\r\n  color: inherit;\r\n}\r\n\n/* 深色主题（Task 10）：html[data-theme='dark'] 覆盖颜色变量与代码 token 配色。\r\n   正文 --fg #e6edf3 与 --bg #0d1117 对比度约 14.7:1（spec §5.4：正文对比 ≥ 4.5:1）。\r\n   末尾 @media 兜底：系统深色但 applyTheme 尚未写入 data-theme 的首屏，避免白闪。 */\r\n\r\nhtml[data-theme='dark'] {\r\n  color-scheme: dark;\r\n\r\n  --bg: #0d1117;\r\n  --bg-elevated: #161b22;\r\n  --bg-muted: #161b22;\r\n  --fg: #e6edf3;\r\n  --fg-muted: #9198a1;\r\n  --border: #30363d;\r\n  --link: #4493f8;\r\n  --link-hover: #79b8ff;\r\n  --accent: #4493f8;\r\n  --selection-bg: #264f78;\r\n\r\n  --code-bg: #161b22;\r\n  --code-fg: #e6edf3;\r\n  --code-border: #30363d;\r\n  --inline-code-bg: rgba(110, 118, 129, 0.4);\r\n\r\n  --blockquote-border: #30363d;\r\n  --blockquote-fg: #9198a1;\r\n  --table-border: #30363d;\r\n  --table-head-bg: #161b22;\r\n  --mark-bg: #3b2300;\r\n  --hr-bg: #30363d;\r\n  --scrollbar-thumb: rgba(110, 118, 129, 0.5);\r\n\r\n  --img-placeholder-bg: #161b22;\r\n  --img-placeholder-border: #30363d;\r\n\r\n  --toc-fg: #9198a1;\r\n  --toc-active-fg: #4493f8;\r\n  --toc-active-bg: rgba(68, 147, 248, 0.15);\r\n\r\n  --toolbar-bg: rgba(13, 17, 23, 0.86);\r\n  --toolbar-border: #30363d;\r\n  --panel-bg: #161b22;\r\n  --panel-shadow: 0 8px 24px rgba(1, 4, 9, 0.8);\r\n  --toast-bg: #e6edf3;\r\n  --toast-fg: #0d1117;\r\n  /* 错误条/大文件横幅（修复波 B-§5.11） */\r\n  --notice-bg: #3b2300;\r\n  --notice-fg: #f0e6c8;\r\n  --notice-border: #9e6a03;\r\n  --notice-error-bg: #3d0f16;\r\n  --notice-error-fg: #ffb3b8;\r\n  --notice-error-border: #cf222e;\r\n  --notice-banner-bg: #0c2d4a;\r\n  --notice-banner-fg: #cae8ff;\r\n  --notice-banner-border: #1f6feb;\r\n\r\n  /* highlight.js token（深色） */\r\n  --hljs-fg: #e6edf3;\r\n  --hljs-comment: #9198a1;\r\n  --hljs-keyword: #ff7b72;\r\n  --hljs-string: #a5d6ff;\r\n  --hljs-number: #79c0ff;\r\n  --hljs-title: #d2a8ff;\r\n  --hljs-built-in: #ffa657;\r\n  --hljs-literal: #79c0ff;\r\n  --hljs-type: #ffa657;\r\n  --hljs-attr: #79c0ff;\r\n  --hljs-variable: #ffa657;\r\n  --hljs-tag: #7ee787;\r\n  --hljs-section: #79c0ff;\r\n  --hljs-meta: #9198a1;\r\n  --hljs-addition-bg: #12261e;\r\n  --hljs-addition-fg: #7ee787;\r\n  --hljs-deletion-bg: #2d1214;\r\n  --hljs-deletion-fg: #ffa198;\r\n}\r\n\r\n/* 首屏兜底：theme.js 写入 data-theme 之前，系统深色时先用深色底（切换无白闪，spec §5.4） */\r\n@media (prefers-color-scheme: dark) {\r\n  html:not([data-theme]) {\r\n    color-scheme: dark;\r\n    --bg: #0d1117;\r\n    --fg: #e6edf3;\r\n    --bg-muted: #161b22;\r\n    --border: #30363d;\r\n    --toolbar-bg: rgba(13, 17, 23, 0.86);\r\n    --toolbar-border: #30363d;\r\n    --panel-bg: #161b22;\r\n    --toast-bg: #e6edf3;\r\n    --toast-fg: #0d1117;\r\n  }\r\n}\r\n\n/* 布局（Task 10）：三栏网格（TOC + 正文滚动列）、侧栏折叠、顶部悬浮工具条、\r\n   正文行宽居中、Aa 排版面板、内联 [TOC]、图片占位框、front matter 属性块、toast。\r\n   只负责结构与间距，颜色全部走变量（light.css / dark.css）。 */\r\n\r\n#app {\r\n  position: relative;\r\n  display: grid;\r\n  /* 两行：第一行是通知条（无通知时高度为 0），第二行铺满剩余视口高度。\r\n     minmax(0,1fr) + 子项 min-height:0 才能让 #toc / #content 各自内部滚动（修复波 E：通知条不再 fixed 覆盖正文）。 */\r\n  grid-template-columns: var(--toc-width) minmax(0, 1fr);\r\n  grid-template-rows: auto minmax(0, 1fr);\r\n  height: 100vh;\r\n  overflow: hidden;\r\n}\r\n\r\n/* 侧栏折叠（Ctrl+B / 工具条「目录」）：保持 DOM，切回不重建 TOC */\r\n#app[data-toc='hidden'] {\r\n  grid-template-columns: 0 minmax(0, 1fr);\r\n}\r\n\r\n#app[data-toc='hidden'] #toc {\r\n  display: none;\r\n}\r\n\r\n/* 顶部悬浮工具条：固定在视口顶部并浮在正文之上（显示/隐藏逻辑见 Task 12 的 shell，默认隐藏） */\r\n#toolbar {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  right: 0;\r\n  z-index: 30;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  height: var(--toolbar-height);\r\n  padding: 0 12px;\r\n  background: var(--toolbar-bg);\r\n  border-bottom: 1px solid var(--toolbar-border);\r\n  backdrop-filter: blur(8px);\r\n}\r\n\r\n#toolbar .toolbar-spacer {\r\n  flex: 1;\r\n}\r\n\r\n#toolbar .tool {\r\n  appearance: none;\r\n  height: 28px;\r\n  padding: 0 10px;\r\n  border: 1px solid transparent;\r\n  border-radius: 6px;\r\n  background: transparent;\r\n  color: var(--fg);\r\n  font: inherit;\r\n  font-size: 13px;\r\n  line-height: 26px;\r\n  cursor: pointer;\r\n}\r\n\r\n#toolbar .tool:hover {\r\n  background: var(--bg-muted);\r\n}\r\n\r\n/* Task 15：导出 PDF 在未打开文档时禁用（禁用态不响应 hover，视觉上也变灰） */\r\n#toolbar .tool:disabled {\r\n  color: var(--fg-muted);\r\n  opacity: 0.55;\r\n  cursor: default;\r\n}\r\n\r\n#toolbar .tool:disabled:hover {\r\n  background: transparent;\r\n}\r\n\r\n#toolbar .tool:focus-visible {\r\n  outline: 2px solid var(--accent);\r\n  outline-offset: 1px;\r\n}\r\n\r\n#toolbar .tool[aria-pressed='false'] {\r\n  color: var(--fg-muted);\r\n}\r\n\r\n#toolbar .tool.active {\r\n  color: var(--accent);\r\n}\r\n\r\n/* 左侧大纲侧栏（独立滚动，不抢正文滚动）：跨通知行与正文行，通知条只在内容列挤占空间 */\r\n#toc {\r\n  grid-column: 1;\r\n  grid-row: 1 / -1;\r\n  min-width: 0;\r\n  min-height: 0;\r\n  overflow-y: auto;\r\n  padding: calc(var(--toolbar-height) + 12px) 12px 32px;\r\n  background: var(--bg);\r\n  border-right: 1px solid var(--border);\r\n}\r\n\r\n#toc nav.toc {\r\n  margin: 0;\r\n}\r\n\r\n#toc nav.toc ol {\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n}\r\n\r\n#toc nav.toc li {\r\n  margin: 1px 0;\r\n}\r\n\r\n#toc nav.toc a {\r\n  display: block;\r\n  padding: 4px 8px;\r\n  border-radius: 6px;\r\n  color: var(--toc-fg);\r\n  font-size: 13px;\r\n  line-height: 1.5;\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n}\r\n\r\n#toc nav.toc a:hover {\r\n  background: var(--bg-muted);\r\n  color: var(--fg);\r\n  text-decoration: none;\r\n}\r\n\r\n#toc nav.toc a.active {\r\n  background: var(--toc-active-bg);\r\n  color: var(--toc-active-fg);\r\n  font-weight: 600;\r\n}\r\n\r\n/* 层级缩进：h1 不缩进，h2–h6 每级 +12px */\r\n#toc nav.toc li[data-level='2'] a {\r\n  padding-left: 20px;\r\n}\r\n\r\n#toc nav.toc li[data-level='3'] a {\r\n  padding-left: 32px;\r\n}\r\n\r\n#toc nav.toc li[data-level='4'] a {\r\n  padding-left: 44px;\r\n}\r\n\r\n#toc nav.toc li[data-level='5'] a {\r\n  padding-left: 56px;\r\n}\r\n\r\n#toc nav.toc li[data-level='6'] a {\r\n  padding-left: 68px;\r\n}\r\n\r\n#toc .toc-empty {\r\n  margin: 4px 0;\r\n  padding: 4px 8px;\r\n  color: var(--fg-muted);\r\n  font-size: 13px;\r\n}\r\n\r\n/* TOC 侧栏拖拽调宽（Task 10 补漏：spec §5.1 要求默认 240 px、可拖 180–360 px）。\r\n   绝对定位在侧栏右缘、不占网格列：#app 仍是两列网格，--toc-width 由 applySettings 写入，\r\n   拖动时实时变化，分隔条用 left: calc(var(--toc-width) - 3px) 跟着走。\r\n   6px 命中区跨在 #toc 的右边框上；::before 是 2px 视觉线（悬停/拖拽时亮 accent）。 */\r\n#app .toc-resizer {\r\n  position: absolute;\r\n  top: 0;\r\n  bottom: 0;\r\n  left: calc(var(--toc-width) - 3px);\r\n  z-index: 25; /* 低于工具条（30）、高于正文列，压住 #toc 的 1px 边框 */\r\n  width: 6px;\r\n  cursor: col-resize;\r\n  touch-action: none;\r\n}\r\n\r\n#app .toc-resizer::before {\r\n  content: '';\r\n  position: absolute;\r\n  top: 0;\r\n  bottom: 0;\r\n  left: 2px;\r\n  width: 2px;\r\n  background: transparent;\r\n  transition: background 120ms ease;\r\n}\r\n\r\n#app .toc-resizer:hover::before,\r\n#app .toc-resizer.dragging::before,\r\n#app .toc-resizer:focus-visible::before {\r\n  background: var(--accent);\r\n}\r\n\r\n#app .toc-resizer:focus-visible {\r\n  outline: 2px solid var(--accent);\r\n  outline-offset: -2px;\r\n}\r\n\r\n/* 折叠时隐藏（hidden 属性由 shell 同步，CSS 再兜一层；两者都要压过上面的定位块） */\r\n#app[data-toc='hidden'] .toc-resizer,\r\n#app .toc-resizer[hidden] {\r\n  display: none;\r\n}\r\n\r\n/* 拖拽期间：全局禁选中 + 保持列宽光标（resizer.js 在 pointerdown/pointerup 切换 .jj-resizing） */\r\nbody.jj-resizing,\r\nbody.jj-resizing * {\r\n  user-select: none !important;\r\n  cursor: col-resize !important;\r\n}\r\n\r\n/* 正文滚动列：标题锚点跳转预留工具条高度（scroll-padding-top），子元素统一居中到行宽 */\r\n#content {\r\n  grid-column: 2;\r\n  grid-row: 2; /* 通知条占第一行；无通知时第一行高度为 0 */\r\n  position: relative; /* 让标题元素的 offsetTop 相对正文滚动列（TOC 滚动联动采集 top 用） */\r\n  min-width: 0;\r\n  min-height: 0;\r\n  overflow-y: auto;\r\n  scroll-behavior: smooth;\r\n  scroll-padding-top: calc(var(--toolbar-height) + 40px);\r\n  /* 行宽居中：用对称 padding 让所有顶层块（含标题，标题自带 margin 会覆盖 auto）都居中 */\r\n  padding: calc(var(--toolbar-height) + 16px) max(28px, calc((100% - var(--content-width)) / 2)) 96px;\r\n}\r\n\r\n#content > * {\r\n  max-width: var(--content-width);\r\n  margin-left: auto;\r\n  margin-right: auto;\r\n}\r\n\r\n/* 代码块横向滚动：超长行不撑破正文列（具体配色/复制按钮在 code.css） */\r\n.code-wrap {\r\n  position: relative;\r\n}\r\n\r\n.code-wrap pre {\r\n  overflow-x: auto;\r\n}\r\n\r\n/* 内联 [TOC]（T9 结构：nav.toc-inline > ol > li[data-level] > a） */\r\nnav.toc-inline {\r\n  margin: 16px auto;\r\n  padding: 10px 16px;\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius);\r\n  background: var(--bg-muted);\r\n  font-size: 0.92em;\r\n}\r\n\r\nnav.toc-inline ol {\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n}\r\n\r\nnav.toc-inline a {\r\n  color: var(--fg-muted);\r\n}\r\n\r\nnav.toc-inline a:hover {\r\n  color: var(--accent);\r\n}\r\n\r\nnav.toc-inline li[data-level='2'] {\r\n  padding-left: 1.1em;\r\n}\r\n\r\nnav.toc-inline li[data-level='3'] {\r\n  padding-left: 2.2em;\r\n}\r\n\r\nnav.toc-inline li[data-level='4'] {\r\n  padding-left: 3.3em;\r\n}\r\n\r\nnav.toc-inline li[data-level='5'] {\r\n  padding-left: 4.4em;\r\n}\r\n\r\nnav.toc-inline li[data-level='6'] {\r\n  padding-left: 5.5em;\r\n}\r\n\r\n/* 图片占位（T9 结构：span.img-placeholder；加载失败/离线时不破版） */\r\n.img-placeholder {\r\n  display: block;\r\n  width: 100%;\r\n  aspect-ratio: 16 / 9;\r\n  margin: 16px auto;\r\n  padding: 8px;\r\n  border: 1px dashed var(--img-placeholder-border);\r\n  border-radius: var(--radius);\r\n  background: var(--img-placeholder-bg);\r\n  color: var(--fg-muted);\r\n  font-size: 13px;\r\n  text-align: center;\r\n  overflow: hidden;\r\n}\r\n\r\n/* front matter 属性块（T9 结构：details.frontmatter > summary + table） */\r\n#content .frontmatter {\r\n  margin: 16px auto;\r\n  padding: 8px 16px;\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius);\r\n  background: var(--bg-muted);\r\n  font-size: 0.92em;\r\n}\r\n\r\n#content .frontmatter summary {\r\n  color: var(--fg-muted);\r\n}\r\n\r\n#content .frontmatter table {\r\n  display: table;\r\n  width: 100%;\r\n  margin: 8px 0;\r\n  border-collapse: collapse;\r\n}\r\n\r\n#content .frontmatter th,\r\n#content .frontmatter td {\r\n  padding: 2px 0;\r\n  border: 0;\r\n  text-align: left;\r\n  vertical-align: top;\r\n}\r\n\r\n#content .frontmatter th {\r\n  width: 9em;\r\n  padding-right: 12px;\r\n  background: transparent;\r\n  color: var(--fg-muted);\r\n  font-weight: 600;\r\n}\r\n\r\n/* Aa 排版面板（浮层） */\r\n.aa-panel {\r\n  position: fixed;\r\n  top: calc(var(--toolbar-height) + 6px);\r\n  right: 12px;\r\n  z-index: 40;\r\n  display: grid;\r\n  gap: 10px;\r\n  width: 264px;\r\n  padding: 14px 16px;\r\n  border: 1px solid var(--border);\r\n  border-radius: 10px;\r\n  background: var(--panel-bg);\r\n  box-shadow: var(--panel-shadow);\r\n}\r\n\r\n/* [hidden] 必须显式压过上面的 display: grid（UA 样式表优先级不够） */\r\n.aa-panel[hidden] {\r\n  display: none;\r\n}\r\n\r\n.aa-row {\r\n  display: grid;\r\n  grid-template-columns: 4.5em 1fr auto;\r\n  gap: 8px;\r\n  align-items: center;\r\n  font-size: 13px;\r\n}\r\n\r\n.aa-row input[type='range'] {\r\n  width: 100%;\r\n  accent-color: var(--accent);\r\n}\r\n\r\n.aa-row select {\r\n  grid-column: 2 / 4;\r\n  height: 26px;\r\n  padding: 0 6px;\r\n  border: 1px solid var(--border);\r\n  border-radius: 6px;\r\n  background: var(--bg-elevated);\r\n  color: var(--fg);\r\n  font: inherit;\r\n  font-size: 13px;\r\n}\r\n\r\n.aa-value {\r\n  width: 2.6em;\r\n  color: var(--fg-muted);\r\n  text-align: right;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* toast 容器（T4 结构：div#toast > div.toast[data-level]）：在正文列内居中（扣除左侧目录宽度），\r\n   目录折叠时回到窗口居中，避免“整窗居中”与正文列不对齐的视觉偏移。 */\r\n#toast {\r\n  position: fixed;\r\n  left: calc(50% + var(--toc-width, 0px) / 2);\r\n  bottom: 24px;\r\n  z-index: 50;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 8px;\r\n  transform: translateX(-50%);\r\n}\r\n\r\n#toast[hidden] {\r\n  display: none;\r\n}\r\n\r\n#app[data-toc='hidden'] #toast {\r\n  left: 50%;\r\n}\r\n\r\n#toast .toast {\r\n  padding: 8px 16px;\r\n  border-radius: 8px;\r\n  background: var(--toast-bg);\r\n  color: var(--toast-fg);\r\n  font-size: 13px;\r\n  box-shadow: var(--panel-shadow);\r\n}\r\n\r\n#toast .toast[data-level='warn'] {\r\n  background: #9a6700;\r\n  color: #ffffff;\r\n}\r\n\r\n#toast .toast[data-level='error'] {\r\n  background: #cf222e;\r\n  color: #ffffff;\r\n}\r\n\r\n/* T11 分块渲染懒加载哨兵：只占 1px，交给 IntersectionObserver 触发下一块；不参与排版 */\r\n#content .chunk-sentinel {\r\n  height: 1px;\r\n  overflow: hidden;\r\n}\r\n\r\n/* ── Task 12：悬浮工具条显隐、阅读进度条、回到顶部、最近文件面板、toast action ── */\r\n\r\n/* 工具条默认隐藏：鼠标进入窗口顶部 40px 或按 Alt 显示（shell 写 #app[data-toolbar]） */\r\n#app[data-toolbar='hidden'] #toolbar {\r\n  display: none;\r\n}\r\n\r\n/* 回到顶部：滚离顶部 > 400px 时由 shell 去掉 hidden；图标按钮（上箭头 + 顶部横线），无文字 */\r\n#back-to-top {\r\n  position: fixed;\r\n  right: 24px;\r\n  bottom: 24px;\r\n  z-index: 30;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 40px;\r\n  height: 40px;\r\n  padding: 0;\r\n  border: 1px solid var(--border);\r\n  border-radius: 999px;\r\n  background: var(--panel-bg);\r\n  color: var(--fg);\r\n  font: inherit;\r\n  box-shadow: var(--panel-shadow);\r\n  cursor: pointer;\r\n}\r\n\r\n#back-to-top .back-to-top-icon {\r\n  display: block;\r\n}\r\n\r\n#back-to-top:hover,\r\n#back-to-top:focus-visible {\r\n  border-color: var(--accent);\r\n  color: var(--accent);\r\n  outline: none;\r\n}\r\n\r\n/* [hidden] 必须显式压过上面的 display（UA 样式表优先级不够时属性会失效） */\r\n#back-to-top[hidden] {\r\n  display: none;\r\n}\r\n\r\n/* 空白启动页的最近文件面板（与工具条菜单共用 renderRecent 的 .recent-* 结构） */\r\n#content .recent-panel {\r\n  max-width: 640px;\r\n  margin: 8vh auto 0;\r\n  padding: 0 4px;\r\n}\r\n\r\n/* 工具条「最近」菜单（spec §5.6）：固定浮层，点击外部/Esc 由 shell 收起 */\r\n#recent-menu {\r\n  position: fixed;\r\n  top: calc(var(--toolbar-height) + 6px);\r\n  right: 12px;\r\n  z-index: 29; /* 在工具条（30）之下、正文之上 */\r\n  width: min(360px, calc(100vw - 24px));\r\n  max-height: min(70vh, 520px);\r\n  overflow-y: auto;\r\n  padding: 12px 14px;\r\n  border: 1px solid var(--border);\r\n  border-radius: 10px;\r\n  background: var(--panel-bg);\r\n  box-shadow: var(--panel-shadow);\r\n}\r\n\r\n#recent-menu[hidden] {\r\n  display: none;\r\n}\r\n\r\n#recent-menu .recent-panel {\r\n  margin: 0;\r\n  padding: 0;\r\n}\r\n\r\n.recent-panel .recent-title {\r\n  margin: 0 0 12px;\r\n  font-size: 1.4em;\r\n  font-weight: 650;\r\n}\r\n\r\n.recent-panel .recent-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n}\r\n\r\n.recent-panel .recent-item {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr) auto;\r\n  grid-auto-rows: auto;\r\n  gap: 2px 12px;\r\n  padding: 10px 14px;\r\n  border: 1px solid var(--border);\r\n  border-radius: 8px;\r\n  background: var(--bg-elevated);\r\n  color: var(--fg);\r\n  font: inherit;\r\n  text-align: left;\r\n  cursor: pointer;\r\n}\r\n\r\n.recent-panel .recent-item:hover,\r\n.recent-panel .recent-item:focus-visible {\r\n  border-color: var(--accent);\r\n  background: var(--bg-muted);\r\n  outline: none;\r\n}\r\n\r\n.recent-panel .recent-name {\r\n  overflow: hidden;\r\n  font-weight: 600;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.recent-panel .recent-dir {\r\n  overflow: hidden;\r\n  color: var(--fg-muted);\r\n  font-size: 12px;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.recent-panel .recent-time {\r\n  grid-column: 2;\r\n  grid-row: 1 / span 2;\r\n  align-self: center;\r\n  color: var(--fg-muted);\r\n  font-size: 12px;\r\n  white-space: nowrap;\r\n}\r\n\r\n.recent-panel .recent-empty {\r\n  margin: 0;\r\n  color: var(--fg-muted);\r\n}\r\n\r\n.recent-panel .recent-hint {\r\n  margin: 16px 0 0;\r\n  color: var(--fg-muted);\r\n  font-size: 13px;\r\n}\r\n\r\n/* toast 可点击 action（「已回到上次位置 · 回到顶部」） */\r\n#toast .toast {\r\n  display: flex;\r\n  gap: 12px;\r\n  align-items: center;\r\n}\r\n\r\n#toast .toast-action {\r\n  appearance: none;\r\n  padding: 2px 10px;\r\n  border: 1px solid currentColor;\r\n  border-radius: 999px;\r\n  background: transparent;\r\n  color: inherit;\r\n  font: inherit;\r\n  font-size: 12px;\r\n  cursor: pointer;\r\n}\r\n\r\n#toast .toast-action:hover {\r\n  background: rgba(255, 255, 255, 0.16);\r\n}\r\n\r\n/* ── Task 14：文件夹浏览（文件树侧栏，复用 --toc-width 与 #toc 的独立滚动） ── */\r\n\r\n/* 侧栏两种内容：大纲（#toc-nav）或文件树（#file-tree）。树模式隐藏大纲，反之隐藏树。\r\n   两者都是 aside 的直接子元素：headings 的 renderToc 只替换 #toc-nav，不会冲掉文件树。 */\r\n#toc-nav {\r\n  min-width: 0;\r\n}\r\n\r\n#toc-nav[hidden] {\r\n  display: none;\r\n}\r\n\r\n#toc[data-sidebar='tree'] #toc-nav {\r\n  display: none;\r\n}\r\n\r\n#toc[data-sidebar='toc'] #file-tree {\r\n  display: none;\r\n}\r\n\r\n#file-tree[hidden] {\r\n  display: none;\r\n}\r\n\r\n#file-tree {\r\n  min-width: 0;\r\n}\r\n\r\n/* 工具条：文件树根目录名与「大纲」返回按钮（未打开文件夹/未在树模式时由 hidden 隐藏） */\r\n#toolbar .tool.browse-root {\r\n  max-width: 180px;\r\n  overflow: hidden;\r\n  color: var(--fg-muted);\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n#toolbar .tool.browse-root.active {\r\n  color: var(--accent);\r\n}\r\n\r\n#toolbar .tool[hidden] {\r\n  display: none;\r\n}\r\n\r\n/* 树节点：三角按钮 + 名称按钮；子列表换行到下一行并缩进 */\r\n.file-tree {\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n  font-size: 13px;\r\n}\r\n\r\n.file-tree li {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: 2px;\r\n  margin: 1px 0;\r\n}\r\n\r\n.file-tree .tree-toggle,\r\n.file-tree .tree-toggle-spacer {\r\n  flex: 0 0 18px;\r\n  width: 18px;\r\n  height: 24px;\r\n}\r\n\r\n.file-tree .tree-toggle {\r\n  appearance: none;\r\n  padding: 0;\r\n  border: 0;\r\n  border-radius: 4px;\r\n  background: transparent;\r\n  color: var(--fg-muted);\r\n  font: inherit;\r\n  font-size: 11px;\r\n  line-height: 24px;\r\n  text-align: center;\r\n  cursor: pointer;\r\n}\r\n\r\n.file-tree .tree-toggle:hover,\r\n.file-tree .tree-toggle:focus-visible {\r\n  background: var(--bg-muted);\r\n  color: var(--fg);\r\n  outline: none;\r\n}\r\n\r\n.file-tree .tree-name {\r\n  appearance: none;\r\n  flex: 1 1 0;\r\n  min-width: 0;\r\n  padding: 3px 6px;\r\n  overflow: hidden;\r\n  border: 0;\r\n  border-radius: 6px;\r\n  background: transparent;\r\n  color: var(--toc-fg);\r\n  font: inherit;\r\n  font-size: 13px;\r\n  line-height: 1.5;\r\n  text-align: left;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  cursor: pointer;\r\n}\r\n\r\n.file-tree .tree-name:hover,\r\n.file-tree .tree-name:focus-visible {\r\n  background: var(--bg-muted);\r\n  color: var(--fg);\r\n  outline: none;\r\n}\r\n\r\n.file-tree li.active > .tree-name {\r\n  background: var(--toc-active-bg);\r\n  color: var(--toc-active-fg);\r\n  font-weight: 600;\r\n}\r\n\r\n.file-tree ul.tree-children {\r\n  flex-basis: 100%;\r\n  margin: 0;\r\n  padding-left: 14px;\r\n  list-style: none;\r\n}\r\n\r\n.file-tree ul.tree-children[hidden] {\r\n  display: none;\r\n}\r\n\r\n#file-tree p.tree-empty,\r\n.file-tree li.tree-empty {\r\n  display: block;\r\n  margin: 4px 0;\r\n  padding: 4px 8px;\r\n  color: var(--fg-muted);\r\n  font-size: 13px;\r\n}\r\n\r\n/* ── 修复波 B-§5.11 / 波 E：内容顶部通知栈（错误条 + 大文件横幅）与渲染兜底 ──\r\n   不再用 fixed 覆盖层压住正文与 TOC 顶部：作为 #app 内容列第一行的网格项，\r\n   有通知时占据高度把正文整体下移（可见时挤占空间而非覆盖），无通知时 [hidden] 让整行高度为 0。\r\n   TOC 跨两行，不被通知挤占也不被遮挡；顶部留白与工具条同高（工具条是 fixed 悬浮层，不压住通知）。\r\n   不自动消失；右侧「关闭」按钮由 shell 绑定。 */\r\n#notice-stack {\r\n  grid-column: 2;\r\n  grid-row: 1;\r\n  z-index: 28;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n  min-width: 0;\r\n  padding: calc(var(--toolbar-height) + 8px) 28px 0;\r\n  /* 容器不拦截滚动/框选，只有通知条本体（含关闭按钮）可交互 */\r\n  pointer-events: none;\r\n}\r\n\r\n#notice-stack > * {\r\n  pointer-events: auto;\r\n}\r\n\r\n/* [hidden] 必须显式压过上面的 display: flex（UA 样式表优先级不够） */\r\n#notice-stack[hidden] {\r\n  display: none;\r\n}\r\n\r\n#error-bar,\r\n#huge-banner {\r\n  display: flex;\r\n  gap: 12px;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  padding: 8px 12px;\r\n  border: 1px solid var(--notice-border);\r\n  border-radius: 8px;\r\n  background: var(--notice-bg);\r\n  color: var(--notice-fg);\r\n  font-size: 13px;\r\n  box-shadow: var(--panel-shadow);\r\n}\r\n\r\n#error-bar {\r\n  border-color: var(--notice-error-border);\r\n  background: var(--notice-error-bg);\r\n  color: var(--notice-error-fg);\r\n}\r\n\r\n#error-bar[data-level='warn'] {\r\n  border-color: var(--notice-border);\r\n  background: var(--notice-bg);\r\n  color: var(--notice-fg);\r\n}\r\n\r\n#huge-banner {\r\n  border-color: var(--notice-banner-border);\r\n  background: var(--notice-banner-bg);\r\n  color: var(--notice-banner-fg);\r\n}\r\n\r\n/* [hidden] 必须显式压过上面的 display: flex（UA 样式表优先级不够） */\r\n#error-bar[hidden],\r\n#huge-banner[hidden] {\r\n  display: none;\r\n}\r\n\r\n#notice-stack .notice-text {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n#notice-stack .notice-close {\r\n  flex: none;\r\n  padding: 2px 10px;\r\n  border: 1px solid currentColor;\r\n  border-radius: 999px;\r\n  background: transparent;\r\n  color: inherit;\r\n  font: inherit;\r\n  font-size: 12px;\r\n  cursor: pointer;\r\n}\r\n\r\n#notice-stack .notice-close:hover,\r\n#notice-stack .notice-close:focus-visible {\r\n  background: rgba(127, 127, 127, 0.18);\r\n  outline: none;\r\n}\r\n\r\n/* 渲染异常兜底：原始 markdown 按纯文本显示（保留换行、可滚动，不撑破布局） */\r\n#content pre.jj-fallback {\r\n  max-width: var(--content-width);\r\n  margin: 0 auto;\r\n  padding: 16px;\r\n  border: 1px solid var(--border);\r\n  border-radius: var(--radius);\r\n  background: var(--code-bg);\r\n  color: var(--code-fg);\r\n  font-family: var(--font-mono);\r\n  font-size: 13px;\r\n  line-height: 1.6;\r\n  white-space: pre-wrap;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 空白启动页「打开文件」按钮（修复波 B-§5.11） */\r\n.recent-panel .recent-open {\r\n  display: inline-block;\r\n  margin: 0 0 14px;\r\n  padding: 8px 18px;\r\n  border: 1px solid var(--accent);\r\n  border-radius: 8px;\r\n  background: transparent;\r\n  color: var(--accent);\r\n  font: inherit;\r\n  font-size: 14px;\r\n  cursor: pointer;\r\n}\r\n\r\n.recent-panel .recent-open:hover,\r\n.recent-panel .recent-open:focus-visible {\r\n  background: var(--toc-active-bg);\r\n  outline: none;\r\n}\r\n\n/* 浅色主题（Task 10）：:root 兜底（首屏 data-theme 尚未写入时）与 html[data-theme='light'] 共用一套色值。\r\n   正文 --fg 与 --bg 对比度约 15.9:1（spec §5.4：正文对比 ≥ 4.5:1，满足 WCAG AA）。\r\n   代码 token 颜色变量由 code.css 的 .hljs-* 规则读取。 */\r\n\r\n:root,\r\nhtml[data-theme='light'] {\r\n  color-scheme: light;\r\n\r\n  --bg: #ffffff;\r\n  --bg-elevated: #ffffff;\r\n  --bg-muted: #f6f8fa;\r\n  --fg: #1f2328;\r\n  --fg-muted: #59636e;\r\n  --border: #d1d9e0;\r\n  --link: #0969da;\r\n  --link-hover: #0349b4;\r\n  --accent: #0969da;\r\n  --selection-bg: #b6ddff;\r\n\r\n  --code-bg: #f6f8fa;\r\n  --code-fg: #1f2328;\r\n  --code-border: #d1d9e0;\r\n  --inline-code-bg: rgba(27, 31, 36, 0.07);\r\n\r\n  --blockquote-border: #d1d9e0;\r\n  --blockquote-fg: #59636e;\r\n  --table-border: #d1d9e0;\r\n  --table-head-bg: #f6f8fa;\r\n  --mark-bg: #fff8c5;\r\n  --hr-bg: #d1d9e0;\r\n  --scrollbar-thumb: rgba(31, 35, 40, 0.25);\r\n\r\n  --img-placeholder-bg: #f6f8fa;\r\n  --img-placeholder-border: #d1d9e0;\r\n\r\n  --toc-fg: #59636e;\r\n  --toc-active-fg: #0969da;\r\n  --toc-active-bg: rgba(9, 105, 218, 0.08);\r\n\r\n  --toolbar-bg: rgba(255, 255, 255, 0.86);\r\n  --toolbar-border: #d1d9e0;\r\n  --panel-bg: #ffffff;\r\n  --panel-shadow: 0 8px 24px rgba(140, 149, 159, 0.2);\r\n  --toast-bg: #1f2328;\r\n  --toast-fg: #ffffff;\r\n  /* 错误条/大文件横幅（修复波 B-§5.11；深色主题在 dark.css 覆盖） */\r\n  --notice-bg: #fff8c5;\r\n  --notice-fg: #3b2300;\r\n  --notice-border: #d4a72c;\r\n  --notice-error-bg: #ffebe9;\r\n  --notice-error-fg: #82071e;\r\n  --notice-error-border: #cf222e;\r\n  --notice-banner-bg: #ddf4ff;\r\n  --notice-banner-fg: #0a3069;\r\n  --notice-banner-border: #54aeff;\r\n\r\n  /* highlight.js token（浅色） */\r\n  --hljs-fg: #1f2328;\r\n  --hljs-comment: #6e7781;\r\n  --hljs-keyword: #cf222e;\r\n  --hljs-string: #0a3069;\r\n  --hljs-number: #0550ae;\r\n  --hljs-title: #8250df;\r\n  --hljs-built-in: #6639ba;\r\n  --hljs-literal: #0550ae;\r\n  --hljs-type: #953800;\r\n  --hljs-attr: #0550ae;\r\n  --hljs-variable: #953800;\r\n  --hljs-tag: #116329;\r\n  --hljs-section: #0550ae;\r\n  --hljs-meta: #6e7781;\r\n  --hljs-addition-bg: #dafbe1;\r\n  --hljs-addition-fg: #116329;\r\n  --hljs-deletion-bg: #ffebe9;\r\n  --hljs-deletion-fg: #cf222e;\r\n}\r\n\n/* 单一界面风格「圆润阅读器风」：参考 Typora / Obsidian 的克制排版——标题层级、引用、\n   表格斑马纹、行内代码、代码块顶栏、TOC 当前项强调条、工具条状态、Aa 面板、最近文件卡片、\n   toast 与细滚动条；圆角略大但不改变排版与交互。\n   只覆盖样式：不改变布局结构、DOM 顺序与任何交互；颜色全部走变量，与 light/dark 组合生效。\n   文件名以 overrides- 开头是为了在构建（按文件名字母序拼接）中排在 light/dark/layout 之后、\n   print.css 之前：本文件的视觉覆盖不会压过打印样式。 */\n\n/* ── 颜色令牌（link 用加深一档的 #3A55E8 保证正文链接对比度 ≥ 4.5:1；强调色仍是 DeepSeek 蓝 #4D6BFE） ── */\n:root {\n  --ui-accent: #4d6bfe;\n  --ui-accent-strong: #3a55e8;\n  --ui-link: #3a55e8;\n  --ui-link-hover: #2438b8;\n  --ui-selection: rgba(77, 107, 254, 0.18);\n  --ui-quote-bg: #f6f8ff;\n  --ui-zebra: #fafbfd;\n  --ui-table-head: #f2f5fc;\n  --ui-code-head: #f1f4fa;\n  --ui-inline-code: #f2f5fb;\n  --ui-card-shadow: 0 6px 20px rgba(32, 48, 96, 0.08);\n}\n\nhtml[data-theme='dark'] {\n  --ui-accent: #8ea4ff;\n  --ui-accent-strong: #b3c2ff;\n  --ui-link: #93a8ff;\n  --ui-link-hover: #c0ccff;\n  --ui-selection: rgba(142, 164, 255, 0.3);\n  --ui-quote-bg: rgba(77, 107, 254, 0.08);\n  --ui-zebra: rgba(255, 255, 255, 0.025);\n  --ui-table-head: rgba(142, 164, 255, 0.1);\n  --ui-code-head: #1b2230;\n  --ui-inline-code: rgba(110, 118, 129, 0.28);\n  --ui-card-shadow: 0 8px 24px rgba(1, 4, 9, 0.55);\n}\n\n/* ── 正文排版 ── */\n::selection {\n  background: var(--ui-selection);\n}\n\n/* 正文链接只做屏幕样式：打印/PDF 由 print.css 统一回落为正文色 + 下划线（评审 Important 1）。 */\n@media screen {\n  #content a {\n    color: var(--ui-link);\n    text-decoration: none;\n  }\n\n  #content a:hover {\n    color: var(--ui-link-hover);\n    text-decoration: underline;\n    text-underline-offset: 0.18em;\n  }\n}\n\n/* h1：层级最大 + 短强调线（3.2em）+ 一条淡下边框；h2 去掉边框弱化；h3 加粗 */\n#content h1 {\n  padding-bottom: 0.45em;\n  border-bottom: 1px solid var(--border);\n  background-image: linear-gradient(90deg, var(--ui-accent), var(--ui-accent));\n  background-repeat: no-repeat;\n  background-position: left bottom;\n  background-size: 3.2em 2px;\n  font-size: 1.9em;\n  font-weight: 700;\n}\n\n#content h2 {\n  padding-bottom: 0;\n  border-bottom: 0;\n  font-size: 1.38em;\n  font-weight: 600;\n}\n\n#content h3 {\n  font-size: 1.16em;\n  font-weight: 700;\n}\n\n#content p {\n  margin: 1em 0;\n}\n\n/* 引用块：3px 强调色左边线 + 浅底 + 右侧圆角 */\n#content blockquote {\n  padding: 0.55em 1em;\n  border-left: 3px solid var(--ui-accent);\n  border-radius: 2px 10px 10px 2px;\n  background: var(--ui-quote-bg);\n  color: var(--blockquote-fg);\n}\n\n/* 表格：圆角 + 表头浅底 + 斑马纹（front matter 表格由下面的 reset 保持原样） */\n#content table {\n  border: 1px solid var(--border);\n  border-collapse: separate;\n  border-spacing: 0;\n  border-radius: 12px;\n  overflow: hidden;\n}\n\n#content th,\n#content td {\n  border: 0;\n  border-right: 1px solid var(--border);\n  border-bottom: 1px solid var(--border);\n}\n\n#content th {\n  background: var(--ui-table-head);\n  font-weight: 600;\n}\n\n#content tr > :last-child {\n  border-right: 0;\n}\n\n#content tbody tr:last-child > td {\n  border-bottom: 0;\n}\n\n#content tbody tr:nth-child(even) > td {\n  background: var(--ui-zebra);\n}\n\n/* front matter 属性表（details.frontmatter）是卡片内的两列键值表，不是正文表格：\n   清掉上面通用表格规则画的外框/表头底/斑马纹，避免与 .frontmatter 卡片形成双边框（评审 Minor 4）。 */\n#content .frontmatter table {\n  border: 0;\n  border-collapse: collapse;\n  border-radius: 0;\n}\n\n#content .frontmatter th,\n#content .frontmatter td,\n#content .frontmatter tbody tr:nth-child(even) > td {\n  border: 0;\n  background: transparent;\n  box-shadow: none;\n}\n\n/* 行内代码：浅底 + 圆角 + 细边（pre > code 不受影响） */\n#content :not(pre) > code {\n  padding: 0.14em 0.38em;\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  background: var(--ui-inline-code);\n  font-size: 0.88em;\n}\n\n/* 代码块：统一的「顶栏」视觉（语言标签 DOM 在渲染管线里不存在，保持不改渲染；顶栏只承载复制按钮） */\n@media screen {\n  #content .code-wrap {\n    overflow: hidden;\n    border: 1px solid var(--code-border);\n    border-radius: 12px;\n    background: var(--code-bg);\n  }\n\n  #content .code-wrap::before {\n    content: '';\n    display: block;\n    height: 32px;\n    border-bottom: 1px solid var(--code-border);\n    background: var(--ui-code-head);\n  }\n\n  #content .code-wrap pre {\n    border: 0;\n    border-radius: 0;\n  }\n\n  #content .code-wrap .copy {\n    top: 4px;\n    right: 8px;\n    height: 24px;\n    border-radius: 6px;\n    line-height: 22px;\n    opacity: 0.7;\n  }\n\n  #content .code-wrap:hover .copy,\n  #content .code-wrap .copy:focus-visible {\n    opacity: 1;\n  }\n}\n\n/* hr：细线 */\n#content hr {\n  height: 1px;\n  margin: 2em 0;\n  border: 0;\n  background: var(--border);\n}\n\n/* 任务清单：复选框用强调色 */\n#content input[type='checkbox'] {\n  width: 1em;\n  height: 1em;\n  accent-color: var(--ui-accent);\n  vertical-align: -0.12em;\n}\n\n/* ── 组件 ── */\n#toolbar .tool {\n  border-radius: 7px;\n  transition:\n    background-color 120ms ease,\n    color 120ms ease;\n}\n\n#toolbar .tool:hover {\n  background: var(--bg-muted);\n}\n\n#toolbar .tool:active {\n  background: var(--border);\n}\n\n#toolbar .tool.active {\n  background: var(--toc-active-bg);\n  /* 文本用加深一档的强调色（#3A55E8 在浅色 active 底上 ≥ 4.5:1）；--ui-accent 只用于条/边框/图标。 */\n  color: var(--ui-accent-strong);\n}\n\n#toolbar .tool:focus-visible {\n  outline: 2px solid var(--ui-accent);\n  outline-offset: 1px;\n}\n\n/* Aa 面板：圆角 + 阴影 + 统一的控件圆角 */\n.aa-panel {\n  border-radius: 14px;\n  box-shadow: var(--ui-card-shadow);\n}\n\n.aa-panel select {\n  border-radius: 7px;\n}\n\n.aa-row input[type='range'] {\n  accent-color: var(--ui-accent);\n}\n\n/* TOC：当前项左侧强调条 */\n#toc nav.toc a {\n  position: relative;\n  border-radius: 8px;\n  transition:\n    background-color 120ms ease,\n    color 120ms ease;\n}\n\n#toc nav.toc a.active {\n  background: var(--toc-active-bg);\n  /* 文本对比度同工具条 active：用 --ui-accent-strong，强调条仍用 --ui-accent。 */\n  color: var(--ui-accent-strong);\n}\n\n#toc nav.toc a.active::before {\n  content: '';\n  position: absolute;\n  top: 5px;\n  bottom: 5px;\n  left: 0;\n  width: 3px;\n  border-radius: 3px;\n  background: var(--ui-accent);\n}\n\n/* 最近文件卡片：hover 轻抬 + 强调色边框 */\n.recent-panel .recent-item {\n  border-radius: 12px;\n  transition:\n    border-color 120ms ease,\n    box-shadow 120ms ease,\n    transform 120ms ease;\n}\n\n.recent-panel .recent-item:hover,\n.recent-panel .recent-item:focus-visible {\n  border-color: var(--ui-accent);\n  box-shadow: var(--ui-card-shadow);\n  transform: translateY(-1px);\n}\n\n/* toast：圆角 + 阴影 */\n#toast .toast {\n  border-radius: 12px;\n  box-shadow: var(--ui-card-shadow);\n}\n\n/* 细窄滚动条（WebKit / WebView2） */\n::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n\n::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n::-webkit-scrollbar-thumb {\n  border: 2px solid transparent;\n  border-radius: 4px;\n  background: var(--scrollbar-thumb);\n  background-clip: content-box;\n}\n\n::-webkit-scrollbar-thumb:hover {\n  background-color: var(--fg-muted);\n  background-clip: content-box;\n}\n\n/* 空状态插画：圆形小尺寸点缀（正文区不放大为主角，也无背景装饰） */\n#content .recent-mascot {\n  display: block;\n  width: 104px;\n  height: 104px;\n  margin: 0 auto 6px;\n  border-radius: 50%;\n  object-fit: cover;\n}\n\n#recent-menu .recent-mascot {\n  display: block;\n  width: 64px;\n  height: 64px;\n  margin: 0 auto 2px;\n  border-radius: 50%;\n  object-fit: cover;\n}\n\n/* 动效偏好：减少动态时不位移（只保留颜色/阴影变化） */\n@media (prefers-reduced-motion: reduce) {\n  .recent-panel .recent-item:hover,\n  .recent-panel .recent-item:focus-visible {\n    transform: none;\n  }\n}\n\n/* ── v3：更圆润（统一大圆角 / 胶囊按钮 / 柔和滚动条） ── */\n:root {\n  --radius: 12px;\n}\n\n/* 工具条与按钮：底角大圆角 + 胶囊按钮 */\n#toolbar {\n  border-radius: 0 0 20px 20px;\n}\n\n#toolbar .tool,\n#toolbar .tool.active,\n#toolbar .tool:focus-visible {\n  border-radius: 999px;\n}\n\n/* 弹层与侧栏：更大的圆角 */\n#recent-menu,\n.aa-panel {\n  border-radius: 22px;\n}\n\n#toc nav.toc {\n  border-radius: 18px;\n}\n\n#toc nav.toc a,\n#toc nav.toc a.active {\n  border-radius: 999px;\n}\n\n/* 最近文件卡片与按钮 */\n.recent-panel .recent-item {\n  border-radius: 18px;\n}\n\n.recent-panel .recent-open {\n  border-radius: 999px;\n}\n\n/* 正文：代码块 / 行内代码 / 图片 / 引用 / 表格 / 分隔线 / 属性表 */\n#content pre,\n#content .code-wrap pre {\n  border-radius: 16px;\n}\n\n#content .code-wrap .copy {\n  border-radius: 999px;\n}\n\n#content :not(pre) > code {\n  border-radius: 7px;\n}\n\n#content img {\n  border-radius: 14px;\n}\n\n#content blockquote {\n  border-radius: 4px 16px 16px 4px;\n}\n\n#content table {\n  border-radius: 14px;\n  overflow: hidden;\n}\n\n#content th:first-child {\n  border-top-left-radius: 14px;\n}\n\n#content th:last-child {\n  border-top-right-radius: 14px;\n}\n\n#content tr:last-child td:first-child {\n  border-bottom-left-radius: 14px;\n}\n\n#content tr:last-child td:last-child {\n  border-bottom-right-radius: 14px;\n}\n\n#content .frontmatter {\n  border-radius: 18px;\n}\n\n/* 通知条 / 错误条 / 大文件横幅 / toast / 回到顶部 */\n#notice-stack > *,\n#huge-banner,\n#error-bar {\n  border-radius: 14px;\n}\n\n#toast .toast,\n#toast .toast-action {\n  border-radius: 999px;\n}\n\n#back-to-top {\n  border-radius: 999px;\n}\n\n/* 排版面板控件 */\n.aa-panel select,\n.aa-row select {\n  border-radius: 10px;\n}\n\n.aa-row input[type='range'] {\n  border-radius: 999px;\n}\n\n.aa-row input[type='range']::-webkit-slider-thumb {\n  border-radius: 50%;\n}\n\n/* 任务清单复选框 */\n#content input[type='checkbox'] {\n  border-radius: 6px;\n}\n\n/* 正文滚动条：细窄 + 圆角滑块（WebKit） */\n#content::-webkit-scrollbar {\n  width: 10px;\n}\n\n#content::-webkit-scrollbar-thumb {\n  border-radius: 999px;\n  background: var(--border-strong, #c9ccd1);\n}\n\n#content::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n/* PDF 导出打印样式（Task 15）：A4 / 12mm 边距；打印模式隐藏界面 chrome、正文全宽白底，\r\n   代码块折行不截断、表格与行尽量不跨页断裂、图片不超出版心、链接带下划线。\r\n   构建按文件名字母序拼接，本文件排在最后，可覆盖 layout/code/light/dark/overrides 的屏幕样式。 */\r\n\r\n@page {\r\n  size: A4;\r\n  margin: 12mm;\r\n}\r\n\r\nbody.print-mode {\r\n  height: auto;\r\n  min-height: 0;\r\n  overflow: visible;\r\n  background: #ffffff;\r\n  color: #1f2328;\r\n}\r\n\r\n/* 打印时把 100vh 的滚动壳展开成文档流：否则 #app 的 overflow:hidden 只会输出一屏 */\r\nbody.print-mode #app {\r\n  display: block;\r\n  height: auto;\r\n  overflow: visible;\r\n}\r\n\r\n/* 隐藏所有界面 chrome（工具条/侧栏/进度条/回到顶部/toast/浮层/通知条/分隔条/代码复制按钮） */\r\nbody.print-mode #toolbar,\r\nbody.print-mode #toc,\r\nbody.print-mode #toc-nav,\r\nbody.print-mode #file-tree,\r\nbody.print-mode #back-to-top,\r\nbody.print-mode #toast,\r\nbody.print-mode #notice-stack,\r\nbody.print-mode #recent-menu,\r\nbody.print-mode #aa-panel,\r\nbody.print-mode .toc-resizer,\r\nbody.print-mode .code-wrap .copy {\r\n  display: none !important;\r\n}\r\n\r\n/* 正文列全宽、白底、去掉阴影/边框；页边距由 @page 与宿主打印设置共同保障 */\r\nbody.print-mode #content {\r\n  width: auto;\r\n  max-width: none;\r\n  margin: 0;\r\n  padding: 0;\r\n  overflow: visible;\r\n  border: 0;\r\n  background: #ffffff;\r\n  box-shadow: none;\r\n}\r\n\r\nbody.print-mode #content > * {\r\n  max-width: none;\r\n  margin-left: 0;\r\n  margin-right: 0;\r\n}\r\n\r\n/* 代码块不截断：超长行折行，不依赖横向滚动（打印时看不到滚动条） */\r\nbody.print-mode pre {\r\n  overflow: visible;\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n}\r\n\r\nbody.print-mode pre code {\r\n  display: block;\r\n}\r\n\r\n/* 表格与行不跨页断裂（超大表格仍会分页，避免整段被推到下一页） */\r\nbody.print-mode table {\r\n  page-break-inside: avoid;\r\n  break-inside: avoid;\r\n}\r\n\r\nbody.print-mode tr {\r\n  page-break-inside: avoid;\r\n  break-inside: avoid;\r\n}\r\n\r\nbody.print-mode img {\r\n  max-width: 100%;\r\n}\r\n\r\n/* 纸面无法悬停：链接保留下划线，颜色继承正文（屏幕的界面风格链接规则限定在 @media screen，\r\n   这里再给打印模式一条明确规则作为双保险；评审 Important 1）。 */\r\nbody.print-mode a,\r\nbody.print-mode #content a {\r\n  color: inherit;\r\n  text-decoration: underline;\r\n}\r\n\r\n/* ── 打印 / PDF 导出时一律回落为纸面样式 ──\r\n   代码块顶栏、空状态插画等装饰隐藏；背景纯白；斑马纹/引用底/卡片阴影不进入纸面。 */\r\nbody.print-mode .recent-mascot,\r\nbody.print-mode .code-wrap::before {\r\n  display: none !important;\r\n}\r\n\r\nbody.print-mode {\r\n  background: #ffffff !important;\r\n  background-image: none !important;\r\n}\r\n\r\nbody.print-mode #app,\r\nbody.print-mode #toc,\r\nbody.print-mode #content {\r\n  background: #ffffff !important;\r\n}\r\n\r\nbody.print-mode #content h1 {\r\n  background-image: none !important;\r\n  /* 界面风格的 h1 装饰（下边框/强调线）不进纸面（评审 Minor 3）。 */\r\n  border-bottom: 0 !important;\r\n  background: none !important;\r\n}\r\n\r\nbody.print-mode #content blockquote,\r\nbody.print-mode #content table,\r\nbody.print-mode #content th,\r\nbody.print-mode #content td,\r\nbody.print-mode #content tbody tr:nth-child(even) > td {\r\n  background: transparent !important;\r\n  box-shadow: none !important;\r\n}\r\n\r\nbody.print-mode #content .code-wrap {\r\n  border: 0;\r\n  background: transparent;\r\n  box-shadow: none;\r\n}\r\n\r\n/* front matter 属性表：纸面保持两列键值排版，不继承界面风格的表格边框/表头底/斑马纹 */\r\nbody.print-mode #content .frontmatter table,\r\nbody.print-mode #content .frontmatter th,\r\nbody.print-mode #content .frontmatter td {\r\n  border: 0 !important;\r\n  background: transparent !important;\r\n  box-shadow: none !important;\r\n}\r\n";
